'use client'

import gsap from 'gsap'
import { createTransition } from './transition-core'
import './transitions.css'

/** Three hand-drawn strokes. Wobbly on purpose — that is where the crayon feel lives. */
const STROKES = [
  'M227.549 1818.76C227.549 1818.76 406.016 2207.75 569.049 2130.26C843.431 1999.85 -264.104 1002.3 227.549 876.262C552.918 792.849 773.647 2456.11 1342.05 2130.26C1885.43 1818.76 14.9644 455.772 760.548 137.262C1342.05 -111.152 1663.5 2266.35 2209.55 1972.76C2755.6 1679.18 1536.63 384.467 1826.55 137.262C2013.5 -22.1463 2209.55 381.262 2209.55 381.262',
  'M1661.28 2255.51C1661.28 2255.51 2311.09 1960.37 2111.78 1817.01C1944.47 1696.67 718.456 2870.17 499.781 2255.51C308.969 1719.17 2457.51 1613.83 2111.78 963.512C1766.05 313.198 427.949 2195.17 132.281 1455.51C-155.219 736.292 2014.78 891.514 1708.78 252.012C1437.81 -314.29 369.471 909.169 132.281 566.512C18.1772 401.672 244.781 193.012 244.781 193.012',
  'M950.5 2450.2C950.5 2450.2 1580.3 2100.8 1350.7 1650.4C1121.1 1200.0 280.6 1850.3 450.2 1350.7C619.8 851.1 1750.4 1450.6 1950.8 950.2C2151.2 449.8 850.3 650.4 650.1 250.6C449.9 -149.2 1250.7 350.8 1250.7 350.8',
]

const paths = (overlay: HTMLDivElement) =>
  Array.from(overlay.querySelectorAll('path'))

/**
 * Crayon wipe.
 *
 * Leaving, each stroke draws itself on while its stroke-width fattens from 200
 * to 700 — that is what turns three lines into a full-screen fill without a
 * separate mask. Entering, they retract off the far end and thin back down.
 *
 *   // app/layout.tsx
 *   <CrayonTransition>{children}</CrayonTransition>
 *
 * Recolour with --crayon-1/2/3 in transitions.css.
 */
export const CrayonTransition = createTransition({
  timeout: 4000,

  overlay: (
    <div className="crayon">
    <svg viewBox="0 0 2453 2535" fill="none" preserveAspectRatio="none">
      {STROKES.map((d, i) => (
        <path
          key={i}
          d={d}
          stroke={`var(--crayon-${i + 1})`}
          strokeWidth={200}
          strokeLinecap="round"
        />
      ))}
    </svg>
    </div>
  ),

  // Dash the strokes to their own length so they start fully retracted.
  setup: (overlay) => {
    paths(overlay).forEach((path) => {
      const length = path.getTotalLength()
      path.style.strokeDasharray = String(length)
      path.style.strokeDashoffset = String(length)
    })
  },

  leave: ({ overlay, done }) => {
    const tl = gsap.timeline({ onComplete: done })

    paths(overlay).forEach((path, i) => {
      tl.to(
        path,
        {
          strokeDashoffset: 0,
          attr: { 'stroke-width': 700 },
          duration: 1,
          ease: 'power1.inOut',
        },
        i * 0.3,
      )
    })

    return () => tl.kill()
  },

  enter: ({ overlay, done }) => {
    const tl = gsap.timeline({ onComplete: done })

    paths(overlay).forEach((path, i) => {
      const length = path.getTotalLength()
      tl.to(
        path,
        {
          strokeDashoffset: -length,
          attr: { 'stroke-width': 200 },
          duration: 1,
          ease: 'power1.inOut',
          // Park it back at the start so the next leave has somewhere to draw from.
          onComplete: () => gsap.set(path, { strokeDashoffset: length }),
        },
        i * 0.1,
      )
    })

    return () => tl.kill()
  },
})

'use client'

import { TransitionRouter } from 'next-transition-router'
import { useEffect, useRef, type ReactNode } from 'react'

/** Passed to every phase. Query your own nodes out of `overlay`. */
export type TransitionContext = {
  overlay: HTMLDivElement
  /** Call when the animation is finished. The navigation waits for this. */
  done: () => void
}

/** A phase may return a cleanup function, called if the phase is interrupted. */
export type Phase = (ctx: TransitionContext) => void | (() => void)

export type TransitionConfig = {
  /** Markup that covers the screen. Rendered once, reused for every navigation. */
  overlay: ReactNode
  /** Runs once after mount — measure paths, set starting state. */
  setup?: (overlay: HTMLDivElement) => void
  /** Plays before the route changes. */
  leave: Phase
  /** Plays after the route changes. */
  enter: Phase
  /**
   * Failsafe. If a phase never calls done() the navigation continues anyway,
   * so a broken animation can never trap someone behind an opaque overlay.
   */
  timeout?: number
}

const DEFAULT_TIMEOUT = 4000

const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/**
 * Turns a transition config into a drop-in provider.
 *
 *   // app/layout.tsx
 *   <CrayonTransition>{children}</CrayonTransition>
 *
 * Engine-agnostic: the phases can use GSAP, Motion, or raw WAAPI. The core only
 * cares that `done()` eventually gets called.
 */
export function createTransition(config: TransitionConfig) {
  const timeout = config.timeout ?? DEFAULT_TIMEOUT

  return function Transition({ children }: { children: ReactNode }) {
    const ref = useRef<HTMLDivElement>(null)

    useEffect(() => {
      if (ref.current) config.setup?.(ref.current)
    }, [])

    const run = (phase: Phase) => (next: () => void) => {
      const overlay = ref.current

      // No overlay yet, or the user asked for less motion — navigate straight through.
      if (!overlay || prefersReducedMotion()) {
        next()
        return
      }

      let settled = false
      const done = () => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        next()
      }
      const timer = setTimeout(() => {
        console.warn(`[transition] phase exceeded ${timeout}ms, continuing`)
        done()
      }, timeout)

      let cleanup: void | (() => void)
      try {
        cleanup = phase({ overlay, done })
      } catch (error) {
        console.error('[transition] phase threw, continuing', error)
        done()
      }

      return () => {
        clearTimeout(timer)
        settled = true
        cleanup?.()
      }
    }

    return (
      <TransitionRouter auto leave={run(config.leave)} enter={run(config.enter)}>
        <div ref={ref} className="transition-overlay" aria-hidden>
          {config.overlay}
        </div>
        {children}
      </TransitionRouter>
    )
  }
}

/* transitions.css — shared styling for every transition in the registry. */

/* ---------- overlay shell (used by all overlay-type transitions) ---------- */

/*
 * 100vw rather than inset:0. A fixed element sized to inset:0 fills the layout
 * viewport, which excludes the scrollbar — so on any page tall enough to
 * scroll, the overlay stops short of the right edge and its centre sits half a
 * scrollbar to the left. 100vw and 100dvh include that strip.
 */
.transition-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100dvh;
  z-index: 100;
  pointer-events: none;
}

.transition-overlay svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* ---------- crayon ---------- */

:root {
  --crayon-1: #ff2d87;
  --crayon-2: #aaff00;
  --crayon-3: #0066ff;
}

.crayon {
  position: absolute;
  inset: 0;
  /* Overscaled so strokes drawn near the edges still cover the corners. */
  transform: scale(1.5);
}

/* Hidden until the first leave phase measures the real path lengths. */
.crayon path {
  stroke-dasharray: 99999;
  stroke-dashoffset: 99999;
}

/* ---------- zipper ---------- */

:root {
  --zip-metal-hi: #ffffff;
  --zip-metal: #d7d2c8;
  --zip-metal-mid: #8f887c;
  --zip-metal-lo: #4a453e;
  --zip-metal-edge: #211f1c;
  --zip-tape: #3d3d46;
  --zip-tape-lo: #26262c;
}

.zip-rig {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
}

.zip-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
}

.zip-band {
  position: absolute;
  width: 100%;
  overflow: hidden;
}

.zip-band-art {
  position: absolute;
}

.zip-slider-layer {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  pointer-events: none;
}

.zip-fill {
  height: 100%;
  width: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .zip-rig { display: none }
}

